        public void LUReusePivot()
        {

            int dim = 6;

            var pivot = new Pivot(dim, Allocator.Temp);

            // First decomposition with the pivot - permutes it.
            var A1 = GenerateOP.floatRandomMat(dim, dim, -5f, 5f, 7777);
            for (int d = 0; d < dim; d++)
                A1[d, d] += 15f;
            var LU1 = new floatMxN(in A1, Allocator.Temp);
            bool s1 = LU.decompInPlace(ref LU1, ref pivot);
            Assert.IsTrue(s1);

            // Second decomposition reuses the SAME pivot object; Reset() must clean it.
            var A2 = GenerateOP.floatRandomMat(dim, dim, -5f, 5f, 9999);
            for (int d = 0; d < dim; d++)
                A2[d, d] += 15f;

            var x_Known = new floatN(dim, Allocator.Temp);
            for (int i = 0; i < dim; i++)
                x_Known[i] = (float)(i + 1);

            var b = Blas.dot(A2, x_Known);

            var LU2 = new floatMxN(in A2, Allocator.Temp);
            bool s2 = LU.decompInPlace(ref LU2, ref pivot);
            Assert.IsTrue(s2);

            var x_Solved = new floatN(in b, Allocator.Temp);
            LU.decompSolve(ref LU2, in pivot, ref x_Solved);

            Assert.IsFalse(Analysis.isAnyNan(in x_Solved));

            AssertVecClose(in x_Known, in x_Solved, dim, 1E-3f);

            pivot.Dispose();
        }

        public void SwapOPTest()
        {

            // Swap.Rows with default start/end swaps full rows.
            {
                int dim = 3;
                var mat = new floatMxN(dim, dim, Allocator.Temp);
                for (int r = 0; r < dim; r++)
                    for (int c = 0; c < dim; c++)
                        mat[r, c] = (float)(r * 10 + c);

                Swap.Rows(ref mat, 0, 1);

                for (int c = 0; c < dim; c++) {
                    AssertClose(mat[0, c], (float)(10 + c), 1E-6f);
                    AssertClose(mat[1, c], (float)(0 + c), 1E-6f);
                    AssertClose(mat[2, c], (float)(20 + c), 1E-6f);
                }
            }

            // Swap.Columns with explicit start/end swaps only that row-range.
            {
                int dim = 4;
                var mat = new floatMxN(dim, dim, Allocator.Temp);
                for (int r = 0; r < dim; r++)
                    for (int c = 0; c < dim; c++)
                        mat[r, c] = (float)(r * 10 + c);

                // swap columns 0 and 1 only for rows [1,3)
                Swap.Columns(ref mat, 0, 1, 1, 3);

                AssertClose(mat[0, 0], (float)(0), 1E-6f);
                AssertClose(mat[0, 1], (float)(1), 1E-6f);
                AssertClose(mat[3, 0], (float)(30), 1E-6f);
                AssertClose(mat[3, 1], (float)(31), 1E-6f);

                AssertClose(mat[1, 0], (float)(11), 1E-6f);
                AssertClose(mat[1, 1], (float)(10), 1E-6f);
                AssertClose(mat[2, 0], (float)(21), 1E-6f);
                AssertClose(mat[2, 1], (float)(20), 1E-6f);

                AssertClose(mat[1, 2], (float)(12), 1E-6f);
                AssertClose(mat[2, 3], (float)(23), 1E-6f);
            }
        }

        public void SolveSystem() {


            int dim = 512;

            var A = GenerateOP.floatRandomMat(dim, dim, -10f, 10f, 314221);

            for (int d = 0; d < dim; d++) {
                A[d, d] *= 2f;
                if (Unity.Mathematics.math.abs(A[d, d]) < 0.01f)
                    A[d, d] *= 10f;
            }

            var x_Known = GenerateOP.floatRandomVec(dim, 1f, 10f, 901);

            var b = Blas.dot(A, x_Known);

            var U = new floatMxN(dim, dim, Allocator.Temp);
            var L = GenerateOP.floatIdentityMat(dim);

            var pivot = new Pivot(dim, Allocator.Temp);

            bool success = LU.decomp(in A, ref L, ref U, ref pivot);

            Assert.IsTrue(success);

            var x_Solved = new floatN(in b, Allocator.Temp);

            LU.decompSolve(ref L, ref U, in pivot, ref x_Solved);

            if (Analysis.isAnyNan(in x_Solved))
                throw new System.Exception("TestJob: NaN detected");

            // Backward-error (residual) gate -- kappa-free, unlike a forward-error check whose floor is
            // kappa(A)*u (~1E-3 at float dim=512, a conditioning lottery, not a solver defect and RHS-fold
            // sensitive). A is intact here, so form the true residual r = A*x_solved - b and normalize by
            // the induced inf-norm: eta = ||r||inf / (||A||inf*||x||inf + ||b||inf). For backward-stable
            // LU this is O(n*u) -- ~1E-5 float, ~1E-14 double -- so one 1E-4 ceiling covers both precisions
            // with margin. The forward error stays only as a loose sanity bound.
            var resid = Blas.dot(A, x_Solved);
            floatComp.subInPlace(resid, b);
            float eta = Norms.LInf(in resid)
                       / (Norms.matrixLInf(in A) * Norms.LInf(in x_Solved) + Norms.LInf(in b));

            var diffKnownSolved = new floatN(in x_Known, Allocator.Temp);
            floatComp.subInPlace(diffKnownSolved, x_Solved);
            var zeroError = Analysis.MaxZeroError(diffKnownSolved);
            float relFwd = zeroError / Norms.LInf(in x_Known);

            // Fail layout: [1]=residual eta, [2]=limit, [3]=diff
            if (!(eta < (float)1E-04f) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = eta;
                Fail[2] = (float)1E-04f;
                Fail[3] = eta - (float)1E-04f;
            }
            Assert.IsTrue(eta < 1E-04f);
            Assert.IsTrue(relFwd < 1E-02f);

            pivot.Dispose();
        }

        // Same Fail-layout convention as SolveSystem above (see there).
        public void SolveSystemInPlace() {


            int dim = 512;

            var A = GenerateOP.floatRandomMat(dim, dim, -10f, 10f, 314221);

            for (int d = 0; d < dim; d++) {
                A[d, d] *= 2f;
                if (Unity.Mathematics.math.abs(A[d, d]) < 0.01f)
                    A[d, d] *= 10f;
            }

            var x_Known = GenerateOP.floatRandomVec(dim, 1f, 10f, 901);

            var b = Blas.dot(A, x_Known);

            var LUmat = new floatMxN(in A, Allocator.Temp);

            var pivot = new Pivot(dim, Allocator.Temp);

            bool success = LU.decompInPlace(ref LUmat, ref pivot);

            Assert.IsTrue(success);

            var x_Solved = new floatN(in b, Allocator.Temp);

            LU.decompSolve(ref LUmat, in pivot, ref x_Solved);

            if (Analysis.isAnyNan(in x_Solved))
                throw new System.Exception("TestJob: NaN detected");

            // Backward-error (residual) gate; see SolveSystem for the full rationale. A is preserved
            // (LUmat is a copy), so eta = ||A*x_solved - b||inf / (||A||inf*||x||inf + ||b||inf) is the
            // kappa-free O(n*u) backward error; forward error kept only as a loose sanity bound.
            var resid = Blas.dot(A, x_Solved);
            floatComp.subInPlace(resid, b);
            float eta = Norms.LInf(in resid)
                       / (Norms.matrixLInf(in A) * Norms.LInf(in x_Solved) + Norms.LInf(in b));

            var diffKnownSolved = new floatN(in x_Known, Allocator.Temp);
            floatComp.subInPlace(diffKnownSolved, x_Solved);
            var zeroError = Analysis.MaxZeroError(diffKnownSolved);
            float relFwd = zeroError / Norms.LInf(in x_Known);

            if (!(eta < (float)1E-04f) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = eta;
                Fail[2] = (float)1E-04f;
                Fail[3] = eta - (float)1E-04f;
            }
            Assert.IsTrue(eta < 1E-04f);
            Assert.IsTrue(relFwd < 1E-02f);

            pivot.Dispose();
        }

        // ================================================================================
        // BLOCKED (level-3) LU coverage.
        //
        // LU.decomp(in A, ref L, ref U, ref P) switches to the LAPACK-style right-looking
        // blocked (compact-WY GEMM trailing update) path at M_Rows >= LU_BLOCK_MIN_N = 8*32 = 256;
        // below that it runs the plain unblocked rank-1 sweep. The blocked path is DESIGNED to keep
        // the partial-pivoting sequence bit-identical to the unblocked form, so it must produce the
        // SAME pivot array and (within GEMM summation-order rounding) the same L/U as the independent,
        // untouched, level-2 compact factorization LU.decompInPlace(ref LU, ref P) — which is
        // used here as the reference ORACLE for both correctness and accuracy.
        //
        // In the in-place compact form: factor row i lives at physical row P[i]; LU[P[i], j] with j < i
        // is the unit-lower L multiplier, and LU[P[i], j] with j >= i is U.
        // ================================================================================

        // (1) N=256: 8 aligned panels of LU_BLOCK=32 — exactly at the gate.
        public void LUBlockedRefAccuracy256()
        {
            int dim = 256;
            var A = MakeWellConditionedPivoting(dim, 260871);
            BlockedVsReference(in A);
        }

        // (2) N=300 = 9*32 + 12 — non-aligned last panel.
        public void LUBlockedRefAccuracy300()
        {
            int dim = 300;
            var A = MakeWellConditionedPivoting(dim, 771013);
            BlockedVsReference(in A);
        }

        // (3) Ill-conditioned N=256: Lehmer (SPD, totally nonnegative, cond < 4n^2 ~ 2.6e5 —
        // genuinely ill-conditioned for float, yet LU never hits a zero pivot). The KEY accuracy
        // test: the blocked backward error ||P A - L U|| stays small AND within a small factor of
        // the unblocked reference's residual on the SAME matrix, i.e. blocking did not amplify error.
        public void LUBlockedIllConditioned256()
        {
            int dim = 256;
            var A = floatGallery.floatLehmer(dim);
            IllConditionedResidual(in A);
        }

        // (4) Singular N=256: an exact duplicate row makes the matrix rank-deficient. Because the two
        // identical rows receive bit-identical updates until one is pivoted (then the other becomes an
        // exact zero row), a zero pivot is guaranteed and the blocked path must return false with no
        // NaN/Inf written.
        public void LUBlockedSingular256()
        {
            int dim = 256;

            var A = GenerateOP.floatRandomMat(dim, dim, 1f, 10f, 55221);
            // strong diagonal dominance so ONLY the duplicated rows cause singularity
            for (int d = 0; d < dim; d++)
                A[d, d] += (float)(2 * dim);
            // make row 137 an exact copy of row 42
            for (int c = 0; c < dim; c++)
                A[137, c] = A[42, c];

            var U = new floatMxN(dim, dim, Allocator.Temp);
            var L = GenerateOP.floatIdentityMat(dim);
            var pivot = new Pivot(dim, Allocator.Temp);

            bool ok = LU.decomp(in A, ref L, ref U, ref pivot);

            Assert.IsFalse(ok);
            Assert.IsFalse(Analysis.isAnyNan(in U));
            Assert.IsFalse(Analysis.isAnyNan(in L));
            Assert.IsFalse(Analysis.isAnyInf(in U));
            Assert.IsFalse(Analysis.isAnyInf(in L));

            pivot.Dispose();
        }

        // (5) Solve round-trip N=300 (non-aligned last panel) using the separate-L/U blocked path.
        // Same recipe / tolerance as the existing dim=512 SolveSystem test.
        public void LUBlockedSolve300()
        {
            int dim = 300;

            var A = GenerateOP.floatRandomMat(dim, dim, -10f, 10f, 314221);

            for (int d = 0; d < dim; d++) {
                A[d, d] *= 2f;
                if (Unity.Mathematics.math.abs(A[d, d]) < 0.01f)
                    A[d, d] *= 10f;
            }

            var x_Known = GenerateOP.floatRandomVec(dim, 1f, 10f, 901);

            var b = Blas.dot(A, x_Known);

            var U = new floatMxN(dim, dim, Allocator.Temp);
            var L = GenerateOP.floatIdentityMat(dim);

            var pivot = new Pivot(dim, Allocator.Temp);

            bool success = LU.decomp(in A, ref L, ref U, ref pivot);

            Assert.IsTrue(success);

            var x_Solved = new floatN(in b, Allocator.Temp);

            LU.decompSolve(ref L, ref U, in pivot, ref x_Solved);

            if (Analysis.isAnyNan(in x_Solved))
                throw new System.Exception("TestJob: NaN detected");

            var diffKnownSolved = new floatN(in x_Known, Allocator.Temp);
            floatComp.subInPlace(diffKnownSolved, x_Solved);
            var zeroError = Analysis.MaxZeroError(diffKnownSolved);

            // x-accuracy is condition-number-amplified (NOT the backward error, which stays ~eps·‖A‖).
            // This fixed random draw at n=300 (cond a few·10^3) lands at ~1.2e-3 max error in float —
            // just over the 1e-3 the dim=512 SolveSystem happens to hit — so use a per-precision band:
            // generous for float, tight for double. Deterministic (fixed seeds), so not flaky.
            float xtol = IsDouble() ? (float)1E-8 : (float)3E-3f;

            if (!(zeroError < xtol) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = zeroError;
                Fail[2] = xtol;
                Fail[3] = zeroError - xtol;
            }
            Assert.IsTrue(zeroError < xtol);

            pivot.Dispose();
        }

        // (6) decompInPlace's OWN blocked (level-3) path vs decomp's blocked path — FULL EQUIVALENCE.
        //
        // After decompInPlace gained its own compact/P-indirected panel/TRSM/GEMM path above
        // LU_BLOCK_MIN_N (float 256, double 128; LU_BLOCK=32), it must produce the IDENTICAL pivot
        // sequence to decomp (full-column-height partial pivoting is schedule-independent) and factors
        // equal within GEMM summation-order rounding. BlockedVsReference is the shared oracle here: it
        // (a) asserts pB == pR elementwise (EXACT int equality — the strong guard: any pivot flip
        // trips it, no tolerance to hide behind), (b) compares decomp's physically-permuted row-i
        // factor against decompInPlace's compact factor READ THROUGH THE PIVOT (LUref[pR[i], j], since
        // "factor row i lives at physical row P[i]") within an ||A||·n·eps·8 absolute tolerance, and
        // (c) checks the blocked backward error is not worse than the reference. BOTH sizes below are
        // above each type's blocked gate, so decomp AND decompInPlace each take their level-3 path.
        //
        // The factor tolerance is NOT vacuous: the true blocked-vs-reference factor gap is
        // O(n·eps·||A||) (~0.02 at float n=288, ||A||~2n), the tolerance is ~8x that (~0.16), and a
        // genuine mismatch (wrong pivot / mis-indexed row) is O(||A||)~576 — three-plus orders above
        // the ceiling. The exact-int pivot check is the primary equivalence assertion.
        public void LUBlockedDecompInPlaceEquivalence()
        {
            // Per-type sizes, both above the blocked gate. First is panel-boundary-aligned
            // (288 = 9*LU_BLOCK float / 160 = 5*LU_BLOCK double, m % 32 == 0); second is one past a
            // boundary (289 / 161 -> a width-1 trailing-panel remainder), so the non-aligned last
            // panel is exercised on BOTH the decomp and decompInPlace sides.
            int sizeBoundary    = 288;
            int sizePastBoundary = 289;

            for (int s = 0; s < 2; s++)
            {
                int dim = (s == 0) ? sizeBoundary : sizePastBoundary;

                // Well-conditioned but NON-trivially pivoting (row-reversed diagonally-dominant), with
                // a column-wise gap wide enough that blocked-vs-unblocked summation rounding cannot
                // flip the argmax -> both paths must pick the SAME pivots (float and double alike).
                var A = MakeWellConditionedPivoting(dim, (uint)(9090711 + s));
                BlockedVsReference(in A);
            }
        }

        // ================================================================================
        // Safe decomp/decompNoPivot preserve A; solveInPlace's exit
        // factor is a usable decompSolve input.
        // ================================================================================

        // LU.decomp and LU.decompNoPivot must not modify A. Checksum (position-weighted sum, so a
        // permutation or a single altered entry both trip it) before/after each call.
        void LUDecompVariantsPreserveA()
        {
            int dim = 9;

            // LU.decomp (pivoted, safe)
            {
                var A = GenerateOP.floatRandomMat(dim, dim, -5f, 5f, 424242);
                for (int d = 0; d < dim; d++) A[d, d] += 15f;
                float checksumBefore = Checksum(in A);

                var L = GenerateOP.floatIdentityMat(dim);
                var U = new floatMxN(dim, dim, Allocator.Temp);
                var pivot = new Pivot(dim, Allocator.Temp);
                bool ok = LU.decomp(in A, ref L, ref U, ref pivot);
                Assert.IsTrue(ok);

                AssertExactEqual(checksumBefore, Checksum(in A));
                pivot.Dispose();
            }

            // LU.decompNoPivot (safe)
            {
                var A = GenerateOP.floatRandomMat(dim, dim, -5f, 5f, 535353);
                for (int d = 0; d < dim; d++) A[d, d] += 15f;
                float checksumBefore = Checksum(in A);

                var L = GenerateOP.floatIdentityMat(dim);
                var U = new floatMxN(dim, dim, Allocator.Temp);
                bool ok = LU.decompNoPivot(in A, ref L, ref U);
                Assert.IsTrue(ok);

                AssertExactEqual(checksumBefore, Checksum(in A));
            }
        }

        // LU.solveInPlace's exit (A_to_LU, P) must be a valid decompSolve input: solving a SECOND
        // right-hand side through it must be bit-identical to a completely independent
        // decompInPlace + decompSolve on the same original matrix.
        void LUSolveInPlaceExitIsUsableFactor()
        {
            int dim = 10;

            // Non-trivial pivoting: MakeWellConditionedPivoting row-reverses a diagonally-dominant
            // matrix, so partial pivoting must undo a genuine (non-identity) permutation. A plain
            // diagonally-dominant fill would swap no rows, hiding any pivot-indexing bug in the fused
            // solveInPlace vs the independent decompInPlace+decompSolve oracle.
            var A = MakeWellConditionedPivoting(dim, 314159);

            var xKnown1 = GenerateOP.floatRandomVec(dim, 1f, 5f, 111);
            var b1 = Blas.dot(A, xKnown1);
            var xKnown2 = GenerateOP.floatRandomVec(dim, 1f, 5f, 222);
            var b2 = Blas.dot(A, xKnown2);

            // path under test: solveInPlace (first RHS), then decompSolve (second RHS) off its exit.
            var Afused = new floatMxN(in A, Allocator.Temp);
            var pivotFused = new Pivot(dim, Allocator.Temp);
            var x1 = new floatN(in b1, Allocator.Temp);
            var info = LU.solveInPlace(ref Afused, ref pivotFused, ref x1);
            Assert.IsTrue(info.Solved);

            var x2 = new floatN(in b2, Allocator.Temp);
            LU.decompSolve(ref Afused, in pivotFused, ref x2);

            // oracle: fresh decompInPlace + decompSolve on an independent copy, same second RHS.
            var Aref = new floatMxN(in A, Allocator.Temp);
            var pivotRef = new Pivot(dim, Allocator.Temp);
            var infoRef = LU.decompInPlace(ref Aref, ref pivotRef);
            Assert.IsTrue(infoRef.Solved);

            var x2ref = new floatN(in b2, Allocator.Temp);
            LU.decompSolve(ref Aref, in pivotRef, ref x2ref);

            for (int i = 0; i < dim; i++)
                AssertExactEqual(x2ref[i], x2[i]);

            pivotFused.Dispose();
            pivotRef.Dispose();
        }

        // (2a) Driver short-circuit purity: LU.solveInPlace on a SINGULAR matrix must (a) report the
        // Singular failure status and (b) leave b_to_x BIT-IDENTICAL to its pre-call snapshot. This
        // guards the `if (!info.Solved) return info;` early return in the fused GESV driver: if that
        // short-circuit were removed, decompSolve would run on the garbage/partial factor and corrupt
        // b_to_x.
        void LUSolveInPlaceShortCircuitPurity()
        {
            int dim = 8;

            // Singular: two identical rows (row 5 == row 2), diagonally boosted so ONLY that
            // duplication causes singularity (reuses LUDecompSingular's construction).
            var A = GenerateOP.floatRandomMat(dim, dim, 1f, 10f, 8821);
            for (int d = 0; d < dim; d++) A[d, d] += 20f;
            for (int c = 0; c < dim; c++) A[5, c] = A[2, c];

            var b = GenerateOP.floatRandomVec(dim, -3f, 3f, 246810);
            var bSnapshot = new floatN(in b, Allocator.Temp); // capture BEFORE the call

            var pivot = new Pivot(dim, Allocator.Temp);
            DirectSolveInfo info = LU.solveInPlace(ref A, ref pivot, ref b);

            // (a) failure status forwarded; not Solved.
            if (info.status != DirectSolveStatus.Singular && Fail[0] == (float)0)
            {
                Fail[0] = (float)1; Fail[1] = (float)(int)info.status;
                Fail[2] = (float)(int)DirectSolveStatus.Singular; Fail[3] = (float)0;
            }
            Assert.IsTrue(info.status == DirectSolveStatus.Singular);
            Assert.IsFalse(info.Solved);

            // (b) b_to_x untouched: bit-identical (==, not within-tolerance) to its snapshot.
            for (int i = 0; i < dim; i++)
                AssertExactEqual(bSnapshot[i], b[i]);

            pivot.Dispose();
        }

        // (2f-i) Blocked-path A-preservation: LU.decomp at dim=256 engages the level-3 blocked
        // (compact-WY GEMM trailing-update) path (LU_BLOCK_MIN_N = 8*32 = 256); it still must not
        // modify A. Checksum (position-weighted) before/after. The existing LUDecompVariantsPreserveA
        // only reaches the unblocked path (dim=9).
        void LUDecompPreservesABlocked()
        {
            int dim = 256;

            var A = MakeWellConditionedPivoting(dim, 424243);
            float checksumBefore = Checksum(in A);

            var L = GenerateOP.floatIdentityMat(dim);
            var U = new floatMxN(dim, dim, Allocator.Temp);
            var pivot = new Pivot(dim, Allocator.Temp);
            bool ok = LU.decomp(in A, ref L, ref U, ref pivot);
            Assert.IsTrue(ok);

            AssertExactEqual(checksumBefore, Checksum(in A));

            pivot.Dispose();
        }

        // ================================================================================
        // TransA API promotion: LU.decompSolveTransA / LU.solveInPlaceTransA solve Aᵀx=b against
        // the SAME compact factor LU.decompInPlace produces (the getrs trans='T' counterpart of
        // decompSolve, promoted from LP.RevisedSimplex's former hand-written BTRAN kernel).
        // ================================================================================

        // (a) Correctness: factor A ONCE (decompInPlace), solve Aᵀx=b via decompSolveTransA, and
        // check it two independent ways: (i) the backward-error residual ||Aᵀx-b|| is small, and
        // (ii) it agrees with a reference computed via the ORDINARY (forward) decompInPlace +
        // decompSolve path run on an EXPLICITLY transposed copy of A -- a completely different code
        // path (different pivot sequence in general, since pivoting Aᵀ is not the same as pivoting A)
        // that must land on the same x.
        void LUDecompSolveTransA()
        {
            int dim = 12;

            // Non-trivial pivoting (see MakeWellConditionedPivoting's own doc) so decompInPlace on A
            // really exercises the pivot, not just an identity permutation.
            var A = MakeWellConditionedPivoting(dim, 555001);

            var At = new floatMxN(dim, dim, Allocator.Temp);
            for (int r = 0; r < dim; r++)
                for (int c = 0; c < dim; c++)
                    At[r, c] = A[c, r];

            var xKnown = GenerateOP.floatRandomVec(dim, 1f, 5f, 777);
            var b = Blas.dot(At, xKnown);

            // ---- path under test: factor A (not At!), solve the TRANSPOSED system ----
            var LUmat = new floatMxN(in A, Allocator.Temp);
            var pivot = new Pivot(dim, Allocator.Temp);
            var info = LU.decompInPlace(ref LUmat, ref pivot);
            Assert.IsTrue(info.Solved);

            var xSolved = new floatN(in b, Allocator.Temp);
            LU.decompSolveTransA(ref LUmat, in pivot, ref xSolved);

            Assert.IsFalse(Analysis.isAnyNan(in xSolved));

            // (i) backward-error residual (same recipe as SolveSystem elsewhere in this file).
            var resid = Blas.dot(At, xSolved);
            floatComp.subInPlace(resid, b);
            float eta = Norms.LInf(in resid)
                       / (Norms.matrixLInf(in At) * Norms.LInf(in xSolved) + Norms.LInf(in b));

            if (!(eta < (float)1E-04f) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1; Fail[1] = eta; Fail[2] = (float)1E-04f; Fail[3] = eta - (float)1E-04f;
            }
            Assert.IsTrue(eta < 1E-04f);

            // (ii) independent reference: ordinary forward decompInPlace + decompSolve on an
            // EXPLICITLY transposed copy of A.
            var AtCopy = new floatMxN(in At, Allocator.Temp);
            var pivotRef = new Pivot(dim, Allocator.Temp);
            var infoRef = LU.decompInPlace(ref AtCopy, ref pivotRef);
            Assert.IsTrue(infoRef.Solved);

            var xRef = new floatN(in b, Allocator.Temp);
            LU.decompSolve(ref AtCopy, in pivotRef, ref xRef);

            AssertVecClose(in xRef, in xSolved, dim, 1E-3f);

            pivot.Dispose();
            pivotRef.Dispose();
        }

        // (b) Matrix-RHS overload consistency: decompSolveTransA(matrix) against the SAME factor,
        // compared column-by-column to decompSolveTransA(vector) run on an INDEPENDENT copy of the
        // same factor. NOT bit-exact: the matrix kernel scales each finalized row by a precomputed
        // reciprocal (Xr[j] *= 1/diag, k multiplies instead of k divides -- the same convention the
        // existing forward triUpperLU/triUpper matrix forms already use), while the vector kernel
        // divides directly (bp[r] /= diag); `x/y` and `x*(1/y)` round to adjacent floats in general,
        // so this is a tight tolerance (single-ULP-scale), not an exact, comparison.
        void LUDecompSolveTransAMatrix()
        {
            int dim = 10;
            int rhsCount = 4;

            var A = MakeWellConditionedPivoting(dim, 4242);
            var B = GenerateOP.floatRandomMat(dim, rhsCount, -3f, 3f, 13131);

            // matrix path
            var LUmatM = new floatMxN(in A, Allocator.Temp);
            var pivotM = new Pivot(dim, Allocator.Temp);
            var infoM0 = LU.decompInPlace(ref LUmatM, ref pivotM);
            Assert.IsTrue(infoM0.Solved);

            var Bsolved = new floatMxN(in B, Allocator.Temp);
            LU.decompSolveTransA(ref LUmatM, in pivotM, ref Bsolved);

            // vector path, column-by-column, against an independently-factored copy
            var LUmatV = new floatMxN(in A, Allocator.Temp);
            var pivotV = new Pivot(dim, Allocator.Temp);
            var infoV0 = LU.decompInPlace(ref LUmatV, ref pivotV);
            Assert.IsTrue(infoV0.Solved);

            float tol = IsDouble() ? (float)1E-10 : (float)1E-5f;
            for (int c = 0; c < rhsCount; c++)
            {
                var col = new floatN(dim, Allocator.Temp);
                for (int r = 0; r < dim; r++) col[r] = B[r, c];

                LU.decompSolveTransA(ref LUmatV, in pivotV, ref col);

                for (int r = 0; r < dim; r++)
                    AssertClose(col[r], Bsolved[r, c], tol);
            }

            pivotM.Dispose();
            pivotV.Dispose();
        }

        // (c) solveInPlaceTransA one-shot (GESV-style: factor + solve in one call) must be
        // bit-identical to the explicit decompInPlace + decompSolveTransA composition, for both the
        // vector and matrix-RHS overloads.
        void LUSolveInPlaceTransAMatchesDecompSolve()
        {
            int dim = 9;

            var A = MakeWellConditionedPivoting(dim, 90909);

            // ---- vector ----
            var b = GenerateOP.floatRandomVec(dim, -4f, 4f, 13579);

            var Afused = new floatMxN(in A, Allocator.Temp);
            var pivotFused = new Pivot(dim, Allocator.Temp);
            var xFused = new floatN(in b, Allocator.Temp);
            var info = LU.solveInPlaceTransA(ref Afused, ref pivotFused, ref xFused);
            Assert.IsTrue(info.Solved);

            var Aref = new floatMxN(in A, Allocator.Temp);
            var pivotRef = new Pivot(dim, Allocator.Temp);
            var infoRef0 = LU.decompInPlace(ref Aref, ref pivotRef);
            Assert.IsTrue(infoRef0.Solved);
            var xRef = new floatN(in b, Allocator.Temp);
            LU.decompSolveTransA(ref Aref, in pivotRef, ref xRef);

            for (int i = 0; i < dim; i++)
                AssertExactEqual(xRef[i], xFused[i]);

            // ---- matrix ----
            int rhsCount = 3;
            var B = GenerateOP.floatRandomMat(dim, rhsCount, -4f, 4f, 24680);

            var Afused2 = new floatMxN(in A, Allocator.Temp);
            var pivotFused2 = new Pivot(dim, Allocator.Temp);
            var Bfused = new floatMxN(in B, Allocator.Temp);
            var infoM = LU.solveInPlaceTransA(ref Afused2, ref pivotFused2, ref Bfused);
            Assert.IsTrue(infoM.Solved);

            var Aref2 = new floatMxN(in A, Allocator.Temp);
            var pivotRef2 = new Pivot(dim, Allocator.Temp);
            var infoRefM0 = LU.decompInPlace(ref Aref2, ref pivotRef2);
            Assert.IsTrue(infoRefM0.Solved);
            var Bref = new floatMxN(in B, Allocator.Temp);
            LU.decompSolveTransA(ref Aref2, in pivotRef2, ref Bref);

            for (int r = 0; r < dim; r++)
                for (int c = 0; c < rhsCount; c++)
                    AssertExactEqual(Bref[r, c], Bfused[r, c]);

            pivotFused.Dispose();
            pivotRef.Dispose();
            pivotFused2.Dispose();
            pivotRef2.Dispose();
        }

        // (d) Singular-matrix handling parity with decompSolve/solveInPlace: solveInPlaceTransA on a
        // singular matrix must (i) report DirectSolveStatus.Singular without solving, and (ii) leave
        // b_to_x / B_to_X bit-identical to their pre-call snapshot (the `if (!info.Solved) return
        // info;` short-circuit, same contract LUSolveInPlaceShortCircuitPurity checks for the forward
        // direction) -- for both the vector and matrix-RHS overloads.
        void LUSolveInPlaceTransASingularParity()
        {
            int dim = 8;

            // ---- vector ----
            var A = GenerateOP.floatRandomMat(dim, dim, 1f, 10f, 8821);
            for (int d = 0; d < dim; d++) A[d, d] += 20f;
            for (int c = 0; c < dim; c++) A[5, c] = A[2, c];   // exact duplicate row -> singular

            var b = GenerateOP.floatRandomVec(dim, -3f, 3f, 135791);
            var bSnapshot = new floatN(in b, Allocator.Temp);

            var pivot = new Pivot(dim, Allocator.Temp);
            DirectSolveInfo info = LU.solveInPlaceTransA(ref A, ref pivot, ref b);

            if (info.status != DirectSolveStatus.Singular && Fail[0] == (float)0)
            {
                Fail[0] = (float)1; Fail[1] = (float)(int)info.status;
                Fail[2] = (float)(int)DirectSolveStatus.Singular; Fail[3] = (float)0;
            }
            Assert.IsTrue(info.status == DirectSolveStatus.Singular);
            Assert.IsFalse(info.Solved);

            for (int i = 0; i < dim; i++)
                AssertExactEqual(bSnapshot[i], b[i]);

            // ---- matrix ----
            var A2 = GenerateOP.floatRandomMat(dim, dim, 1f, 10f, 8821);
            for (int d = 0; d < dim; d++) A2[d, d] += 20f;
            for (int c = 0; c < dim; c++) A2[5, c] = A2[2, c];

            var B = GenerateOP.floatRandomMat(dim, 3, -3f, 3f, 246813);
            var Bsnapshot = new floatMxN(in B, Allocator.Temp);

            var pivot2 = new Pivot(dim, Allocator.Temp);
            DirectSolveInfo infoM = LU.solveInPlaceTransA(ref A2, ref pivot2, ref B);

            Assert.IsTrue(infoM.status == DirectSolveStatus.Singular);
            Assert.IsFalse(infoM.Solved);

            for (int r = 0; r < dim; r++)
                for (int c = 0; c < 3; c++)
                    AssertExactEqual(Bsnapshot[r, c], B[r, c]);

            pivot.Dispose();
            pivot2.Dispose();
        }

        // Position-weighted sum: differs if ANY entry changes or two entries are transposed.
        private float Checksum(in floatMxN M)
        {
            float s = (float)0;
            for (int i = 0; i < M.Length; i++)
                s += M[i] * (float)(i + 1);
            return s;
        }

        // Fail layout: [1]=got, [2]=expected, [3]=diff
        private void AssertExactEqual(float expected, float got)
        {
            if (got != expected && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = got;
                Fail[2] = expected;
                Fail[3] = got - expected;
            }
            Assert.IsTrue(got == expected);
        }

        // true only when float expands to double (doubleEpsilon ≈ 2.2e-16 < 1e-10).
        private bool IsDouble() => (double)Consts.floatEpsilon < 1e-10;

        // Well-conditioned input that forces a NONTRIVIAL but UNAMBIGUOUS pivot sequence: a strongly
        // (row+column) diagonally-dominant random matrix (each column has one big entry, all others
        // small) with its rows reversed. Partial pivoting must undo the reversal; the huge column-wise
        // gap (~2*dim vs ~1) means the argmax is robust to GEMM-vs-scalar summation-order rounding, so
        // the blocked and unblocked factorizations pick the SAME pivots for BOTH float and double.
        private floatMxN MakeWellConditionedPivoting(int dim, uint seed)
        {
            var A = GenerateOP.floatRandomMat(dim, dim, -1f, 1f, seed);
            for (int d = 0; d < dim; d++)
                A[d, d] += (float)(2 * dim);
            for (int i = 0; i < dim / 2; i++)
                Swap.Rows(ref A, i, dim - 1 - i);
            return A;
        }

        // Points (1)/(2): blocked LU.decomp (in A, ref L, ref U, ref P) vs unblocked compact LU.decompInPlace (2-arg) oracle.
        // Asserts identical pivots, matching L/U factors, and no backward-error regression.
        private void BlockedVsReference(in floatMxN A)
        {
            int dim = A.M_Rows;

            // --- blocked path (separate L, U, P) ---
            var U = new floatMxN(dim, dim, Allocator.Temp);
            var L = GenerateOP.floatIdentityMat(dim);
            var pB = new Pivot(dim, Allocator.Temp);
            bool okB = LU.decomp(in A, ref L, ref U, ref pB);
            Assert.IsTrue(okB);
            Assert.IsFalse(Analysis.isAnyNan(in U));
            Assert.IsFalse(Analysis.isAnyNan(in L));

            // --- reference: independent unblocked compact in-place factorization ---
            var LUref = new floatMxN(in A, Allocator.Temp);
            var pR = new Pivot(dim, Allocator.Temp);
            bool okR = LU.decompInPlace(ref LUref, ref pR);
            Assert.IsTrue(okR);

            // (a) pivot arrays identical elementwise
            AssertPivotEqual(in pB, in pR, dim);

            // (b) factor accuracy: blocked L (strict lower) & U (upper) match the reference compact
            //     form at physical row pR[i]. Absolute tolerance scaled by matrix magnitude, matrix
            //     size (accumulation length) and machine eps — loose for float, tight for double.
            float aScale = MatMaxAbs(in A);
            float factorTol = (aScale + (float)1) * (float)dim * Consts.floatEpsilon * (float)8;
            float maxFactorDiff = (float)0;
            for (int i = 0; i < dim; i++) {
                int prow = pR[i];
                for (int j = 0; j < dim; j++) {
                    float refVal = LUref[prow, j];
                    float blkVal = (j < i) ? L[i, j] : U[i, j];
                    maxFactorDiff = Unity.Mathematics.math.max(maxFactorDiff, Unity.Mathematics.math.abs(refVal - blkVal));
                }
            }
            if (!(maxFactorDiff <= factorTol) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1; Fail[1] = maxFactorDiff; Fail[2] = factorTol; Fail[3] = maxFactorDiff - factorTol;
            }
            Assert.IsTrue(maxFactorDiff <= factorTol);

            // (c) backward error: ||P A - L U|| for blocked vs reference (rebuilt from compact form).
            float resBlocked = ResidualPALU(in A, in L, in U, in pB);

            var refL = GenerateOP.floatIdentityMat(dim);
            var refU = new floatMxN(dim, dim, Allocator.Temp);
            for (int i = 0; i < dim; i++) {
                int prow = pR[i];
                for (int j = 0; j < dim; j++) {
                    if (j < i) refL[i, j] = LUref[prow, j];
                    else       refU[i, j] = LUref[prow, j];
                }
            }
            float resRef = ResidualPALU(in A, in refL, in refU, in pR);

            AssertResidualNotWorse(dim, aScale, resBlocked, resRef);

            pB.Dispose();
            pR.Dispose();
        }

        // Point (3): ill-conditioned residual comparison ONLY (no pivot/factor identity, since a
        // rounding-induced pivot flip is legitimate on a near-degenerate matrix).
        private void IllConditionedResidual(in floatMxN A)
        {
            int dim = A.M_Rows;

            var U = new floatMxN(dim, dim, Allocator.Temp);
            var L = GenerateOP.floatIdentityMat(dim);
            var pB = new Pivot(dim, Allocator.Temp);
            bool okB = LU.decomp(in A, ref L, ref U, ref pB);
            Assert.IsTrue(okB);
            Assert.IsFalse(Analysis.isAnyNan(in U));
            Assert.IsFalse(Analysis.isAnyNan(in L));

            var LUref = new floatMxN(in A, Allocator.Temp);
            var pR = new Pivot(dim, Allocator.Temp);
            bool okR = LU.decompInPlace(ref LUref, ref pR);
            Assert.IsTrue(okR);

            float resBlocked = ResidualPALU(in A, in L, in U, in pB);

            var refL = GenerateOP.floatIdentityMat(dim);
            var refU = new floatMxN(dim, dim, Allocator.Temp);
            for (int i = 0; i < dim; i++) {
                int prow = pR[i];
                for (int j = 0; j < dim; j++) {
                    if (j < i) refL[i, j] = LUref[prow, j];
                    else       refU[i, j] = LUref[prow, j];
                }
            }
            float resRef = ResidualPALU(in A, in refL, in refU, in pR);

            float aScale = MatMaxAbs(in A);
            AssertResidualNotWorse(dim, aScale, resBlocked, resRef);

            pB.Dispose();
            pR.Dispose();
        }

        // resBlocked must (i) stay within the O(n * sqrt(eps) * ||A||) backward-error ceiling (the true
        // backward error is O(n * eps * ||A||), well below this) and (ii) be within a small factor of
        // the unblocked reference residual — the accuracy-regression guard.
        private void AssertResidualNotWorse(int dim, float aScale, float resBlocked, float resRef)
        {
            float ceiling = (aScale + (float)1) * (float)dim * Consts.floatSqrtEps;
            if (!(resBlocked <= ceiling) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1; Fail[1] = resBlocked; Fail[2] = ceiling; Fail[3] = resBlocked - ceiling;
            }
            Assert.IsTrue(resBlocked <= ceiling);

            float resFloor = (aScale + (float)1) * (float)dim * Consts.floatEpsilon;
            float resLimit = (float)16 * resRef + resFloor;
            if (!(resBlocked <= resLimit) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1; Fail[1] = resBlocked; Fail[2] = resRef; Fail[3] = resBlocked - resLimit;
            }
            Assert.IsTrue(resBlocked <= resLimit);
        }

        // ||P A - L U||_max : apply the inverse row pivot to a copy of A (PA = LU convention, matching
        // AssertLU's usage) then compare against L*U.
        private float ResidualPALU(in floatMxN A, in floatMxN L, in floatMxN U, in Pivot P)
        {
            var Aperm = new floatMxN(in A, Allocator.Temp);
            P.ApplyInverseRow(ref Aperm);
            var shouldBeZero = new floatMxN(in Aperm, Allocator.Temp);
            floatComp.subInPlace(shouldBeZero, Blas.dot(L, U));
            return Analysis.MaxZeroError(shouldBeZero);
        }

        private void AssertPivotEqual(in Pivot a, in Pivot b, int dim)
        {
            for (int i = 0; i < dim; i++) {
                if (a[i] != b[i] && Fail[0] == (float)0)
                {
                    Fail[0] = (float)1; Fail[1] = (float)a[i]; Fail[2] = (float)b[i]; Fail[3] = (float)i;
                }
                Assert.IsTrue(a[i] == b[i]);
            }
        }

        // max |A[i,j]| — matrix magnitude, used to scale backward-stable tolerances.
        private float MatMaxAbs(in floatMxN A)
        {
            float mx = (float)0;
            for (int i = 0; i < A.Length; i++)
                mx = Unity.Mathematics.math.max(mx, Unity.Mathematics.math.abs(A[i]));
            return mx;
        }

        // Fail layout: [0]=flag, [1]=got, [2]=expected/limit, [3]=diff
        private void AssertClose(float a, float b, float precision) {
            float diff = Unity.Mathematics.math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = a;
                Fail[2] = b;
                Fail[3] = diff;
            }
            Assert.IsTrue(diff <= precision);
        }

        // Fail layout: [0]=flag, [1]=got, [2]=expected, [3]=relative diff
        private void AssertCloseRel(float a, float b, float relPrecision) {
            float denom = Unity.Mathematics.math.max((float)1f, Unity.Mathematics.math.abs(b));
            float diff = Unity.Mathematics.math.abs(a - b) / denom;
            if (!(diff <= relPrecision) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = a;
                Fail[2] = b;
                Fail[3] = diff;
            }
            Assert.IsTrue(diff <= relPrecision);
        }

        // Fail layout: [0]=flag, [1]=got[i], [2]=expected[i], [3]=index cast to float
        private void AssertVecClose(in floatN expected, in floatN got, int dim, float precision) {
            for (int i = 0; i < dim; i++) {
                float diff = Unity.Mathematics.math.abs(expected[i] - got[i]);
                if (!(diff <= precision) && Fail[0] == (float)0)
                {
                    Fail[0] = (float)1;
                    Fail[1] = got[i];
                    Fail[2] = expected[i];
                    Fail[3] = (float)i;
                }
                Assert.IsTrue(diff <= precision);
            }
        }

        private void AssertLU(in floatMxN A, in floatMxN L, in floatMxN U, bool pivoted) => AssertLU(in A, in L, in U, pivoted, 1E-6f);
        private void AssertLU(in floatMxN A, in floatMxN L, in floatMxN U, bool pivoted, float precision)
        {
            floatMxN shouldBeZero = new floatMxN(in A, Allocator.Temp);
            floatComp.subInPlace(shouldBeZero, Blas.dot(L, U));

            if (Analysis.isAnyNan(in shouldBeZero))
                throw new System.Exception("TestJob: NaN detected");

            // Fail layout: [1]=maxZeroError, [2]=precision, [3]=diff
            var zeroError = Analysis.MaxZeroError(shouldBeZero);
            if (!(zeroError <= precision) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = zeroError;
                Fail[2] = precision;
                Fail[3] = zeroError - precision;
            }
            Assert.IsTrue(Analysis.isZero(in shouldBeZero, precision));
            Assert.IsTrue(Analysis.isLowerTriangular(L, precision));
            Assert.IsTrue(Analysis.isUpperTriangular(U, precision));

            if(pivoted)
            unsafe {
                var maxAbs = LinearAlgebra.Internal.UnsafeOP.maxAbs(L.Data.Ptr, L.Length);

                if(maxAbs > 1f)
                    throw new System.Exception("TestJob: L has values greater than 1f");
            }
        }

    }

    public static Array GetEnums() {
        return Enum.GetValues(typeof(TestJob.TestType));
    }

    [TestCaseSource("GetEnums")]
    public void LUDecompTests(TestJob.TestType type)
    {
        var fail = new NativeArray<float>(4, Allocator.TempJob);
        try {
            new TestJob() { Type = type, Fail = fail }.Run();
            // Under Burst a failed in-job assert logs an exception and aborts the job without
            // throwing to the caller - surface the recorded diagnostics here as well.
            if (fail[0] != (float)0)
                Assert.Fail($"got {fail[1]}, expected/limit {fail[2]}, diff/extra {fail[3]}");

        }
        catch (Exception e) {
            if (fail[0] != (float)0)
                Assert.Fail($"{type}: got {fail[1]}, expected/limit {fail[2]}, diff/extra {fail[3]} ({e.Message})");
            throw;
        }
        finally {
            fail.Dispose();
        }
    }

}
